fn sha256(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}

fn bytes_from_hex(value: &Value) -> Vec<u8> {
    let text = value.as_str().expect("frozen bytes must be hex");
    assert_eq!(text.len() % 2, 0);
    (0..text.len())
        .step_by(2)
        .map(|offset| u8::from_str_radix(&text[offset..offset + 2], 16).unwrap())
        .collect()
}

fn source_state(root: &Path) -> BTreeMap<String, Vec<u8>> {
    let mut result = BTreeMap::new();
    let mut pending = vec![root.to_path_buf()];
    while let Some(directory) = pending.pop() {
        for item in fs::read_dir(directory).unwrap() {
            let path = item.unwrap().path();
            if path.is_dir() {
                pending.push(path);
            } else {
                let relative = path
                    .strip_prefix(root)
                    .unwrap()
                    .to_str()
                    .unwrap()
                    .to_owned();
                result.insert(relative, fs::read(path).unwrap());
            }
        }
    }
    result
}

fn original_rows(target: &Value, inputs: &Value) -> Vec<Value> {
    let runs = target["runs"].as_array().unwrap();
    assert_eq!(runs.len(), 2);
    let mut previous = None;
    for (index, run) in runs.iter().enumerate() {
        assert_eq!(run["attempt"], index + 1);
        assert_eq!(run["exit"], 2);
        let stdout = bytes_from_hex(&run["stdout_hex"]);
        let stderr = bytes_from_hex(&run["stderr_hex"]);
        assert_eq!(sha256(&stdout), run["stdout_sha256"].as_str().unwrap());
        assert_eq!(sha256(&stderr), run["stderr_sha256"].as_str().unwrap());
        assert!(stderr.is_empty());
        let argv = run["argv"].as_array().unwrap();
        let offset = argv.iter().position(|arg| arg == "--output=json").unwrap();
        assert_eq!(&argv[offset + 1..], inputs.as_array().unwrap().as_slice());
        let offset = argv
            .iter()
            .position(|arg| arg == "--python-version")
            .unwrap();
        assert_eq!(argv[offset + 1], target["target"]);
        let current = (run["exit"].clone(), stdout, stderr);
        if let Some(previous) = &previous {
            assert_eq!(previous, &current, "original repeat bytes changed");
        }
        previous = Some(current);
    }
    let (_, stdout, _) = previous.unwrap();
    stdout
        .split(|byte| *byte == b'\n')
        .filter(|line| !line.is_empty())
        .map(|line| serde_json::from_slice(line).expect("frozen original JSON row"))
        .collect()
}

fn actual_rows(report: &ToolReport, root: &Path) -> Vec<Value> {
    report
        .diagnostics
        .iter()
        .map(|diagnostic| {
            let location = &diagnostic.location;
            let serialized = serde_json::to_value(diagnostic).unwrap();
            assert!(diagnostic.fix.is_none());
            assert_eq!(location.offset, None);
            assert_eq!(location.end_offset, None);
            // The native public location starts at column 1. Original JSON starts
            // at column 0. End columns retain their existing value without change.
            // The native unpositioned sentinel is u32::MAX with start column 0;
            // original JSON reports line -1 and start column -1 for that sentinel.
            let column = if location.line == QualityLocation::UNPOSITIONED_LINE {
                assert_eq!(location.column, 0);
                -1_i64
            } else {
                i64::from(
                    location
                        .column
                        .checked_sub(1)
                        .expect("one-based start column"),
                )
            };
            json!({
                "file":diagnostic.path.strip_prefix(root).unwrap().to_str().unwrap(),
                "line":serialized["location"]["line"], "column":column,
                "end_line":serialized["location"]["end_line"], "end_column":location.end_column,
                "message":diagnostic.message, "hint":diagnostic.hint,
                "code":serialized["rule"], "severity":diagnostic.severity,
            })
        })
        .collect()
}

fn write_evidence(name: &str, target: &str, evidence: &Value) {
    let Some(directory) = std::env::var_os("MAMBA_QUALITY_MYPY_LOCAL_OWNER_PRIORITY_EVIDENCE_DIR")
    else {
        return;
    };
    let directory = PathBuf::from(directory);
    assert!(directory.is_dir(), "evidence directory must exist");
    let mut file = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(directory.join(format!("{name}-{target}.json")))
        .unwrap();
    serde_json::to_writer_pretty(&mut file, evidence).unwrap();
    file.write_all(b"\n").unwrap();
    file.sync_all().unwrap();
}

fn run_cell(name: &str, target_index: usize) {
    assert_eq!(sha256(FIXTURE.as_bytes()), FIXTURE_SHA256);
    let cases: Vec<Value> = serde_json::from_str(FIXTURE).unwrap();
    assert_eq!(cases.len(), 6);
    let case = cases.iter().find(|case| case["name"] == name).unwrap();
    let target = &case["targets"][target_index];
    let target_name = target["target"].as_str().unwrap();
    let expected = original_rows(target, &case["inputs"]);
    // Keep all selected files within one existing repository project boundary.
    // A plain external temp directory has no project marker and would assign
    // pkg/mod.py to a different native project from main.py.
    let repository = Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .unwrap()
        .parent()
        .unwrap();
    let temp = tempfile::Builder::new()
        .prefix("mamba-local-owner-priority-")
        .tempdir_in(repository.join("target"))
        .unwrap();
    let root = fs::canonicalize(temp.path()).unwrap();
    let mut expected_source = BTreeMap::new();
    for entry in case["entries"].as_array().unwrap() {
        let relative = entry["path"].as_str().unwrap();
        let bytes = bytes_from_hex(&entry["bytes_hex"]);
        assert_eq!(sha256(&bytes), entry["sha256"].as_str().unwrap());
        assert_eq!(bytes.len(), entry["bytes"].as_u64().unwrap() as usize);
        let path = root.join(relative);
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(path, &bytes).unwrap();
        expected_source.insert(relative.to_owned(), bytes);
    }
    if name == "03-dependency-decode-versus-owner" {
        assert_eq!(expected_source["broken_dep.py"], vec![0xff, b'\n']);
    }
    let source_before = source_state(&root);
    assert_eq!(source_before, expected_source);
    // Preserve input order. Do not collect these paths through a map or a set.
    let inputs: Vec<_> = case["inputs"]
        .as_array()
        .unwrap()
        .iter()
        .map(|input| root.join(input.as_str().unwrap()))
        .collect();
    let mut workspace = Filesystem.load(&inputs, true);
    let actual_requests: Vec<_> = workspace
        .source_requests
        .iter()
        .map(|request| request.path.clone())
        .collect();
    assert_eq!(actual_requests, inputs);
    let version = match target_name {
        "3.12" => PythonVersion::Py312,
        "3.13" => PythonVersion::Py313,
        "3.14" => PythonVersion::Py314,
        other => panic!("unexpected Python target {other}"),
    };
    for project in &mut workspace.projects {
        project.python_version = version;
    }
    let report = super::super::check(&workspace);
    let actual = actual_rows(&report, &root);
    let source_after = source_state(&root);
    let diagnostics_match = actual == expected;
    let status_match = report.completion == CompletionStatus::Error
        && report.reference_exit_code == Some(2)
        && report.checked_files == 0;
    let source_preserved = source_before == source_after;
    let identity_match = report.tool == QualityTool::Mypy && report.reference_version == "2.4.0";
    let issues: Vec<_> = workspace
        .issues
        .iter()
        .map(|issue| json!({"code":issue.code,"message":issue.message,"path":issue.path}))
        .collect();
    let passed = diagnostics_match
        && status_match
        && source_preserved
        && identity_match
        && issues.is_empty()
        && !report.remaining.is_empty();
    write_evidence(
        name,
        target_name,
        &json!({
            "schema":"mamba.quality.mypy-local-owner-priority-native-cell.v1",
            "case":name,"target":target_name,"inputs":case["inputs"],"native_inputs":inputs,
            "fixture_sha256":FIXTURE_SHA256,"source_entries":case["entries"],
            "source_before":source_before,"source_after":source_after,
            "original_runs":target["runs"],"expected_diagnostics":expected,"actual_diagnostics":actual,
            "workspace_issues":issues,"actual_tool_report":report,
            "comparisons":{"diagnostics_match":diagnostics_match,"status_match":status_match,
                "source_preserved":source_preserved,"identity_match":identity_match},
            "passed":passed,"whole_plan_accepted":false,
        }),
    );
    assert!(
        passed,
        "local-owner priority differs for {name}/{target_name}; evidence is saved if enabled"
    );
}

macro_rules! cell {
    ($function:ident, $case:literal, $target:expr) => {
        #[test]
        fn $function() {
            run_cell($case, $target);
        }
    };
}

